const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const volcano = ee.Geometry.Point([122.775, -8.532]); // Mount Lewotobi Laki-Laki
  const westRegion = ee.Geometry.Point([122.675, -8.532]).buffer(5000); // 5km west
  const eastRegion = ee.Geometry.Point([122.875, -8.532]).buffer(5000); // 5km east

  // July 7, 2025, 2 PM local time (UTC+8) = 06:00 UTC
  const targetDate = '2025-07-07';
  const startDate = '2025-07-06';
  const endDate = '2025-07-08';

  // 2. Data Acquisition
  let col = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
    .filterBounds(volcano)
    .filterDate(startDate, endDate)
    .sort('system:time_start');

  const colSize = col.size().getInfo();
  console.log(`Sentinel-2 images found: ${colSize}`);

  if (colSize === 0) {
    // Try Landsat 8/9
    col = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(volcano)
      .filterDate(startDate, endDate);

    const landsatSize = col.size().getInfo();
    console.log(`Landsat images found: ${landsatSize}`);

    if (landsatSize === 0) {
      console.log('No imagery available for the specified date.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // Get the closest image to target time
  const img = ee.Image(col.first());
  const imgDate = new Date(img.get('system:time_start').getInfo());
  console.log(`Using image from: ${imgDate.toISOString()}`);

  // 3. Aerosol/Plume Detection (using Aerosol band or RGB composite)
  let aerosol;
  if (img.bandNames().contains('B1').getInfo()) {
    // Sentinel-2: Use aerosol band (B1) or create aerosol index
    aerosol = img.select('B1'); // Coastal aerosol band
  } else {
    // Landsat: Use SR_QA_AEROSOL or blue band as proxy
    aerosol = img.select('SR_B2'); // Blue band
  }

  // 4. Calculate aerosol signal in west vs east regions
  const westStats = aerosol.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: westRegion,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const eastStats = aerosol.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: eastRegion,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const westMean = westStats.B1_mean || westStats.SR_B2_mean;
  const westCount = westStats.B1_count || westStats.SR_B2_count;
  const eastMean = eastStats.B1_mean || eastStats.SR_B2_mean;
  const eastCount = eastStats.B1_count || eastStats.SR_B2_count;

  console.log(`West region - Mean: ${westMean}, Pixels: ${westCount}`);
  console.log(`East region - Mean: ${eastMean}, Pixels: ${eastCount}`);

  // 5. Validation & Final Answer
  if (westCount === 0 || eastCount === 0) {
    console.log('No valid pixels in comparison regions.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (westMean == null || eastMean == null || isNaN(westMean) || isNaN(eastMean)) {
    console.log('Calculation failed - invalid values.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Westward plume means higher aerosol signal to the west
  const ratio = westMean / eastMean;
  console.log(`West/East aerosol ratio: ${ratio.toFixed(2)}`);

  if (ratio > 1.15) {
    console.log('Volcanic plume detected drifting westward.');
    console.log('<answer>A</answer>');
  } else {
    console.log('No significant westward plume drift detected.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
